<script lang="ts">import PageShell from '$lib/components/PageShell.svelte';import {users} from '$lib/api';let name=$state(''),location=$state(''),saved=$state(false);async function save(){await users.update({name,location});saved=true}</script><PageShell eyebrow="SETTINGS" title="Keep your details current."><form class="form-card narrow" onsubmit={(e)=>{e.preventDefault();save()}}><label>Name<input bind:value={name} placeholder="Your name"/></label><label>Location<input bind:value={location} placeholder="Nairobi, Kenya"/></label><button class="btn primary">Save changes</button>{#if saved}<p class="success">Saved.</p>{/if}</form></PageShell>
